public class CapacityCacheTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        CapacityCache<String, Integer> cache = new CapacityCache<>(2);
        cache.put("a", 1);
        cache.put("b", 2);
        cache.get("a");
        cache.put("c", 3);

        check("get(b) after eviction", null, cache.get("b"));
        check("get(a) survived", 1, cache.get("a"));
        check("get(c)", 3, cache.get("c"));
        check("size()", 2, cache.size());
        check("hits()", 3, cache.hits());
        check("misses()", 1, cache.misses());
        check("keysOldestFirst()", "[a, c]", String.valueOf(cache.keysOldestFirst()));

        CapacityCache<String, String> words = new CapacityCache<>(2);
        words.put("k", "one");
        words.put("k", "two");
        words.put("j", "three");
        check("re-put replaces without evicting", "two", words.get("k"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

