import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CapacityCache<K, V> {

    private final int capacity;
    private final Map<K, V> entries = new HashMap<>();
    private final List<K> usage = new ArrayList<>();
    private int hits = 0;
    private int misses = 0;

    public CapacityCache(int capacity) {
        this.capacity = capacity;
    }

    public void put(K key, V value) {
        entries.put(key, value);
        usage.remove(key);
        usage.add(key);
        while (usage.size() > capacity) {
            K oldest = usage.remove(0);
            entries.remove(oldest);
        }
    }

    public V get(K key) {
        if (!entries.containsKey(key)) {
            misses++;
            return null;
        }
        hits++;
        usage.remove(key);
        usage.add(key);
        return entries.get(key);
    }

    public int size() {
        return entries.size();
    }

    public int hits() {
        return hits;
    }

    public int misses() {
        return misses;
    }

    public List<K> keysOldestFirst() {
        return new ArrayList<>(usage);
    }
}
